<?phpsession_start();require_once "db.php";if (!isset($_SESSION['admin_id'])) {    header("Location: index.php");    exit();}if (empty($_SESSION['dashboard_csrf'])) {    $_SESSION['dashboard_csrf'] = bin2hex(random_bytes(32));}$message = "";$messageType = "";// APPROVE / REJECT REGISTRATIONif ($_SERVER["REQUEST_METHOD"] === "POST") {    $token = $_POST['csrf_token'] ?? '';    if (!hash_equals($_SESSION['dashboard_csrf'], $token)) {        $message = "Invalid request. Please refresh the page.";        $messageType = "error";    } else {        $role = $_POST['role'] ?? '';        $userId = filter_input(INPUT_POST, 'user_id', FILTER_VALIDATE_INT);        $action = $_POST['approval_action'] ?? '';        $tables = [            'student' => ['table' => 'students', 'id' => 'student_id'],            'teacher' => ['table' => 'teachers', 'id' => 'teacher_id']        ];        if (            isset($tables[$role]) &&            $userId &&            in_array($action, ['approve', 'reject'], true)        ) {            $table = $tables[$role]['table'];            $idColumn = $tables[$role]['id'];            $newStatus = ($action === 'approve') ? 'approved' : 'rejected';            $sql = "UPDATE $table                    SET status = $1                    WHERE $idColumn = $2 AND status = 'pending'";            $result = pg_query_params(                $conn,                $sql,                [$newStatus, $userId]            );            if ($result && pg_affected_rows($result) > 0) {                $message = ucfirst($role) . " account " . $newStatus . " successfully.";                $messageType = "success";            } else {                $message = "Unable to update account. Please check the record.";                $messageType = "error";            }        } else {            $message = "Invalid approval request.";            $messageType = "error";        }    }}// COUNT RECORDSfunction getCount($conn, $table) {    $allowed = ['students', 'teachers', 'subjects'];    if (!in_array($table, $allowed, true)) {        return 0;    }    $result = pg_query($conn, "SELECT COUNT(*) FROM $table");    return $result ? (int)pg_fetch_result($result, 0, 0) : 0;}function getPendingCount($conn, $table) {    if (!in_array($table, ['students', 'teachers'], true)) {        return 0;    }    $result = pg_query_params(        $conn,        "SELECT COUNT(*) FROM $table WHERE status = $1",        ['pending']    );    return $result ? (int)pg_fetch_result($result, 0, 0) : 0;}$totalStudents = getCount($conn, 'students');$totalTeachers = getCount($conn, 'teachers');$totalSubjects = getCount($conn, 'subjects');$pendingStudents = getPendingCount($conn, 'students');$pendingTeachers = getPendingCount($conn, 'teachers');// PENDING STUDENT LIST$studentResult = pg_query(    $conn,    "SELECT student_id, student_name, roll_number, email     FROM students     WHERE status = 'pending'     ORDER BY student_id DESC");// PENDING TEACHER LIST$teacherResult = pg_query(    $conn,    "SELECT teacher_id, teacher_name, employee_id, department, email     FROM teachers     WHERE status = 'pending'     ORDER BY teacher_id DESC");// TODAY'S ATTENDANCE$today = date('Y-m-d');$presentResult = pg_query_params(    $conn,    "SELECT COUNT(*) FROM attendance     WHERE attendance_date = $1 AND status = 'Present'",    [$today]);$absentResult = pg_query_params(    $conn,    "SELECT COUNT(*) FROM attendance     WHERE attendance_date = $1 AND status = 'Absent'",    [$today]);$present = $presentResult ? (int)pg_fetch_result($presentResult, 0, 0) : 0;$absent = $absentResult ? (int)pg_fetch_result($absentResult, 0, 0) : 0;$todayAttendance = $present + $absent;$username = htmlspecialchars($_SESSION['username'] ?? 'Admin');function e($value) {    return htmlspecialchars((string)$value, ENT_QUOTES, 'UTF-8');}?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>SmartAttend | Admin Dashboard</title><link rel="stylesheet" href="dashboard.css"><style>.approval-section {    background: white;    padding: 25px;    margin-top: 30px;    border-radius: 14px;    box-shadow: 0 4px 15px rgba(0,0,0,0.05);    overflow-x: auto;}.approval-section h2 {    margin-bottom: 20px;    color: #263653;}.approval-table {    width: 100%;    border-collapse: collapse;    min-width: 650px;}.approval-table th,.approval-table td {    padding: 14px;    text-align: left;    border-bottom: 1px solid #edf0f5;}.approval-table th {    background: #f5f7fb;    color: #536078;}.approve-btn,.reject-btn {    padding: 9px 14px;    border: none;    border-radius: 7px;    color: white;    cursor: pointer;    margin: 3px;}.approve-btn {    background: #16a34a;}.reject-btn {    background: #dc2626;}.no-pending {    color: #777;    padding: 15px 0;}.pending-cards {    display: flex;    gap: 20px;    margin-top: 25px;    flex-wrap: wrap;}.pending-card {    background: white;    padding: 20px;    border-radius: 12px;    flex: 1;    min-width: 180px;    box-shadow: 0 4px 15px rgba(0,0,0,0.05);}.pending-card h2 {    color: #5367e8;    margin-top: 10px;}.dashboard-message {    padding: 14px;    border-radius: 8px;    margin: 20px 0;}.dashboard-message.success {    background: #dcfce7;    color: #166534;}.dashboard-message.error {    background: #fee2e2;    color: #991b1b;}@media(max-width:600px) {    .approval-section {        padding: 15px;    }}</style></head><body><div class="sidebar">    <h2>College Portal</h2>    <a href="dashboard.php" class="active">Dashboard</a>    <a href="student.php">Students</a>    <a href="teacher.php">Teachers</a>    <a href="subject.php">Subjects</a>    <a href="attendance.php">Attendance</a>    <a href="report.php">Attendance Report</a>    <a href="logout.php">Logout</a></div><div class="main">    <div class="topbar">        <div>            <h1>Admin Dashboard</h1>            <p>College Attendance Management System</p>        </div>        <div class="admin">            Welcome, <?php echo $username; ?>        </div>    </div>    <?php if ($message !== ""): ?>        <div class="dashboard-message <?php echo e($messageType); ?>">            <?php echo e($message); ?>        </div>    <?php endif; ?>    <h2 class="welcome">Dashboard Overview</h2>    <div class="cards">        <a href="student.php" class="card blue">            <h3>Total Students</h3>            <h1><?php echo $totalStudents; ?></h1>            <p>Registered Students</p>        </a>        <a href="teacher.php" class="card green">            <h3>Total Teachers</h3>            <h1><?php echo $totalTeachers; ?></h1>            <p>Registered Teachers</p>        </a>        <a href="subject.php" class="card purple">            <h3>Total Subjects</h3>            <h1><?php echo $totalSubjects; ?></h1>            <p>Available Subjects</p>        </a>        <a href="attendance.php" class="card purple">            <h3>Today's Attendance</h3>            <h1><?php echo $todayAttendance; ?></h1>            <p>Total Attendance</p>        </a>    </div>    <div class="pending-cards">        <div class="pending-card">            <p>Pending Students</p>            <h2><?php echo $pendingStudents; ?></h2>        </div>        <div class="pending-card">            <p>Pending Teachers</p>            <h2><?php echo $pendingTeachers; ?></h2>        </div>    </div>    <!-- STUDENT APPROVAL -->    <div class="approval-section">        <h2>Pending Student Registrations</h2>        <?php if ($studentResult && pg_num_rows($studentResult) > 0): ?>        <table class="approval-table">            <tr>                <th>Name</th>                <th>Roll Number</th>                <th>Email</th>                <th>Action</th>            </tr>            <?php while ($student = pg_fetch_assoc($studentResult)): ?>            <tr>                <td><?php echo e($student['student_name']); ?></td>                <td><?php echo e($student['roll_number']); ?></td>                <td><?php echo e($student['email']); ?></td>                <td>                    <form method="POST">                        <input type="hidden" name="csrf_token"                               value="<?php echo e($_SESSION['dashboard_csrf']); ?>">                        <input type="hidden" name="role" value="student">                        <input type="hidden" name="user_id"                               value="<?php echo (int)$student['student_id']; ?>">                        <button class="approve-btn"                                name="approval_action"                                value="approve">                            Approve                        </button>                        <button class="reject-btn"                                name="approval_action"                                value="reject"                                onclick="return confirm('Reject this student registration?')">                            Reject                        </button>                    </form>                </td>            </tr>            <?php endwhile; ?>        </table>        <?php else: ?>            <p class="no-pending">No pending student registrations.</p>        <?php endif; ?>    </div>    <!-- TEACHER APPROVAL -->    <div class="approval-section">        <h2>Pending Teacher Registrations</h2>        <?php if ($teacherResult && pg_num_rows($teacherResult) > 0): ?>        <table class="approval-table">            <tr>                <th>Name</th>                <th>Employee ID</th>                <th>Department</th>                <th>Email</th>                <th>Action</th>            </tr>            <?php while ($teacher = pg_fetch_assoc($teacherResult)): ?>            <tr>                <td><?php echo e($teacher['teacher_name']); ?></td>                <td><?php echo e($teacher['employee_id']); ?></td>                <td><?php echo e($teacher['department']); ?></td>                <td><?php echo e($teacher['email']); ?></td>                <td>                    <form method="POST">                        <input type="hidden" name="csrf_token"                               value="<?php echo e($_SESSION['dashboard_csrf']); ?>">                        <input type="hidden" name="role" value="teacher">                        <input type="hidden" name="user_id"                               value="<?php echo (int)$teacher['teacher_id']; ?>">                        <button class="approve-btn"                                name="approval_action"                                value="approve">                            Approve                        </button>                        <button class="reject-btn"                                name="approval_action"                                value="reject"                                onclick="return confirm('Reject this teacher registration?')">                            Reject                        </button>                    </form>                </td>            </tr>            <?php endwhile; ?>        </table>        <?php else: ?>            <p class="no-pending">No pending teacher registrations.</p>        <?php endif; ?>    </div>    <div class="attendance-section">        <h2>Today's Attendance Summary</h2>        <div class="attendance-cards">            <div class="attendance-card present">                <h3>Present Students</h3>                <h1><?php echo $present; ?></h1>            </div>            <div class="attendance-card absent">                <h3>Absent Students</h3>                <h1><?php echo $absent; ?></h1>            </div>        </div>    </div></div></body></html>